/*
 (1) COMPOSITION: watch mesh (2.2u tall) centered above a low plinth (r1.4, h0.25, top y=-1.1),
     backdrop gradient plane 7x6 at z=-2.5, contact shadow disc under plinth, headline/body/caption text block below.
 (2) LIGHT RIG: rig-product-hero — warm key spot (65) up-right, cool point fill (4) left, white rim spot (48) back-left,
     plus a node-local #ff2a38 accent rim point grazing the left case flank (intensity <=1.5).
 (3) MATERIALS: brushed-metal PBR override on watch (rough 0.52, metal 0.55, clearcoat 0.2) kept only if GLB lacks maps;
     plinth MeshStandardNodeMaterial #14141a rough 0.7 metal 0.3; backdrop TSL vertical 3-stop gradient; TSL radial shadow.
 (4) MOTION: orbit primitive on load (0.15 rad/s), depth-rotate on hover (6deg), weighted-settle overshoot 1.04->1.0
     on release via gsap; entrance rise-in 0.7s power3.out.
 (5) FOCAL: the key-lit watch case — single brightest element; accent red confined to left bezel rim highlight.
*/
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, float, sub, length, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, SpotLight, PointLight, Object3D, Color, DoubleSide } = ctx.THREE;

  const COLORS = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10', surface: '#14141a', ink: '#16161d',
    paper: '#e8ecf2', accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#0b0b10' }, { at: 0.55, hex: '#101017' }, { at: 1, hex: '#16161d' }],
  };

  const root = new Group();
  root.name = 'orbit-product-hero';
  const disposables = [];
  const timelines = [];
  const primCleanups = [];

  // ---- backdropGradient: stage plane 7x6 at z=-2.5, 3-stop vertical gradient ----
  const stops = COLORS.gradientStops ?? [];
  const c0 = new Color(stops[0]?.hex ?? COLORS.background);
  const c1 = new Color(stops[1]?.hex ?? '#101017');
  const c2 = new Color(stops[2]?.hex ?? COLORS.ink);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const t = uv().y;
    const a = mix(vec3(c0.r, c0.g, c0.b), vec3(c1.r, c1.g, c1.b), smoothstep(float(0.0), float(0.55), t));
    backdropMat.colorNode = mix(a, vec3(c2.r, c2.g, c2.b), smoothstep(float(0.55), float(1.0), t));
  }
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---- heroGroup: watch + plinth + shadow (orbit / depth-rotate target) ----
  const heroGroup = new Group();
  heroGroup.name = 'heroGroup';
  root.add(heroGroup);

  // ---- plinthMesh: low cylinder, top face at y=-1.1 ----
  const plinthGeo = new CylinderGeometry(1.4, 1.45, 0.25, 64);
  const plinthMat = new MeshStandardNodeMaterial({
    color: new Color(COLORS.surface ?? '#14141a'),
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinth = new Mesh(plinthGeo, plinthMat);
  plinth.position.y = -1.1 - 0.125;
  heroGroup.add(plinth);
  disposables.push(plinthGeo, plinthMat);

  // ---- contactShadow: radial gradient disc under plinth, opacity 0.55 ----
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false, side: DoubleSide });
  {
    const d = length(sub(uv(), vec2(0.5, 0.5))).mul(2.0);
    shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
    shadowMat.opacityNode = smoothstep(float(1.0), float(0.15), d).mul(0.55);
  }
  const shadowGeo = new PlaneGeometry(3.2, 3.2);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -1.1 - 0.25 - 0.005;
  heroGroup.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---- watchMesh: GLB load, normalize to 2.2 units tall, brushed-metal PBR fallback ----
  const brushedMat = new MeshPhysicalNodeMaterial({
    color: new Color('#c9ced6'),
    roughness: 0.52,
    metalness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
  });
  disposables.push(brushedMat);
  const watchHolder = new Group();
  watchHolder.name = 'watchHolder';
  heroGroup.add(watchHolder);
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const scene = gltf.scene ?? gltf.scenes?.[0];
    if (!scene) return;
    // normalize height to 2.2 scene units, center at origin
    const box = new ctx.THREE.Box3().setFromObject(scene);
    const size = new ctx.THREE.Vector3();
    box.getSize(size);
    const s = 2.2 / Math.max(size.y, 1e-6);
    scene.scale.setScalar(s);
    const center = new ctx.THREE.Vector3();
    box.getCenter(center);
    scene.position.set(-center.x * s, -center.y * s, -center.z * s);
    scene.traverse((o) => {
      if (o.isMesh) {
        if (!o.material || !o.material.map) {
          o.material = brushedMat;
        }
        disposables.push(o.geometry);
        if (o.material !== brushedMat) disposables.push(o.material);
      }
    });
    watchHolder.add(scene);
    // rise-in entrance
    watchHolder.position.y = 0.4;
    const tl = gsap.timeline();
    tl.to(watchHolder.position, { y: 0, duration: 0.7, ease: 'power3.out' });
    tl.fromTo(watchHolder.scale, { x: 1.04, y: 1.04, z: 1.04 }, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.3);
    timelines.push(tl);
  });

  // ---- lightRig: rig-product-hero (key spot / fill point / rim spot) + accentRim ----
  const lights = new Group();
  lights.name = 'lightRig';
  root.add(lights);
  const R = 1.4; // subject bounding radius

  const key = new SpotLight(new Color('#fff2e0'), 65, 0, 0.5, 0.55, 2);
  key.position.set(2.2 * R, 3.2 * R, 2.4 * R);
  const keyTarget = new Object3D();
  keyTarget.position.set(0, 0.5, 0);
  key.target = keyTarget;
  lights.add(key, keyTarget);

  const fill = new PointLight(new Color('#d8dde6'), 4, 9, 2);
  fill.position.set(-2.8 * R, 0.9 * R, 2 * R);
  lights.add(fill);

  const rim = new SpotLight(new Color('#ffffff'), 48, 0, 0.6, 0.4, 2);
  rim.position.set(-1.6 * R, 2.6 * R, -2.2 * R);
  const rimTarget = new Object3D();
  rimTarget.position.set(0, 0.7, 0);
  rim.target = rimTarget;
  lights.add(rim, rimTarget);

  // accent signal light grazing the left case flank (#ff2a38, intensity <=1.5)
  const accentRim = new PointLight(new Color(COLORS.accent ?? '#ff2a38'), 1.5, 5, 2);
  accentRim.position.set(-2.0, 0.2, -0.6);
  lights.add(accentRim);

  // ---- textBlock: MSDF text via ctx.fontAtlas ----
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [
    { text: 'Calibre NA-01', role: 'headline', typography: { fontSize: 68 } },
    { text: 'Machined in-house. 41 mm. Grade 5 titanium.', role: 'body', typography: { fontSize: 26 } },
    { text: 'FROM 4200 USD / SHIPS IN 21 DAYS', role: 'caption', typography: { fontSize: 18 } },
  ];
  const textGroup = new Group();
  textGroup.name = 'textBlock';
  const roleY = { headline: -1.5, body: -1.85, caption: -2.0 };
  const roleOpts = {
    headline: { color: COLORS.paper ?? '#e8ecf2', align: 'center' },
    body: { color: COLORS.paper ?? '#e8ecf2', align: 'center' },
    caption: { color: COLORS.accent ?? '#ff2a38', align: 'center', letterSpacingPx: 1.5 },
  };
  for (const item of textItems) {
    const role = item.role ?? 'body';
    const opts = roleOpts[role] ?? roleOpts.body;
    const mesh = ctx.fontAtlas.createText(String(item.text), {
      fontSize: item.typography?.fontSize ?? 26,
      color: opts.color,
      align: opts.align,
      letterSpacingPx: opts.letterSpacingPx,
      maxWidthPx: 900,
    });
    mesh.position.set(0, roleY[role] ?? -1.85, 0.4);
    textGroup.add(mesh);
  }
  root.add(textGroup);
  // fade-up entrance for text
  textGroup.position.y = -0.2;
  const textTl = gsap.timeline();
  textTl.to(textGroup.position, { y: 0, duration: 0.5, ease: 'power2.out', delay: 0.2 });
  timelines.push(textTl);

  // ---- cinematicPrimitives: apply every configured primitive via ctx.primitives ----
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives[p.name];
    if (typeof fn === 'function') {
      const r = fn(heroGroup, p.params ?? {});
      if (r?.cleanup) primCleanups.push(r.cleanup);
      if (r?.timeline) timelines.push(r.timeline);
    }
  }

  // ---- handlers: hover settle with weighted overshoot ----
  root.userData.handlers = {
    pointerdown: () => {
      const tl = gsap.timeline();
      tl.to(heroGroup.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
      timelines.push(tl);
    },
    pointerup: () => {
      const tl = gsap.timeline();
      tl.to(heroGroup.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.25, ease: 'power2.out' })
        .to(heroGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
      timelines.push(tl);
    },
    pointerleave: () => {
      const tl = gsap.timeline();
      tl.to(heroGroup.rotation, { x: 0, z: 0, duration: 0.9, ease: 'power4.out' });
      timelines.push(tl);
    },
  };

  // ---- cleanup ----
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const c of primCleanups) { try { c(); } catch (_) {} }
    for (const d of disposables) { try { d.dispose?.(); } catch (_) {} }
    key.dispose?.(); fill.dispose?.(); rim.dispose?.(); accentRim.dispose?.();
    root.clear();
  };

  return root;
}

/* @spec-manifest
{"elements":[
{"id":"text.headline.0","where":"textBlock","how":"fontAtlas.createText from textContent items"},
{"id":"text.body.1","where":"textBlock","how":"fontAtlas.createText from textContent items"},
{"id":"text.caption.2","where":"textBlock","how":"caption rendered in accent red"},
{"id":"color.background","where":"backdropGradient","how":"gradient stop 0 #0b0b10"},
{"id":"color.surface","where":"plinthMesh","how":"plinth base color #14141a"},
{"id":"color.ink","where":"backdropGradient","how":"gradient stop 1 #16161d"},
{"id":"color.paper","where":"textBlock","how":"headline/body text color #e8ecf2"},
{"id":"color.accent","where":"lightRig","how":"accentRim light + caption color"},
{"id":"color.gradient","where":"backdropGradient","how":"TSL 3-stop vertical smoothstep mix"},
{"id":"effects.spec","where":"watchMesh","how":"GLB normalized 2.2u, plinth, shadow, rig"},
{"id":"primitive.orbit","where":"cinematicPrimitives","how":"ctx.primitives['orbit'](heroGroup, params)"},
{"id":"primitive.depth-rotate","where":"cinematicPrimitives","how":"ctx.primitives['depth-rotate'](heroGroup, params)"}
]}
*/
